import { WiDaySunny, WiCloudy, WiDayCloudy, WiRain, WiThunderstorm, WiSnow, WiFog } from 'react-icons/wi'; // use: npm install react-icons

const WeatherIcon = ({ condition }) => {
    const lowerCondition = condition.toLowerCase();
    
    if (lowerCondition.includes('clear') || lowerCondition.includes('sun')) {
      return <WiDaySunny className="weather-icon" />;
    }
    else if (lowerCondition.includes('few clouds') || lowerCondition.includes('scattered clouds')) {
      return <WiDayCloudy className="weather-icon" />;
    }
    else if (lowerCondition.includes('cloud')) {
      return <WiCloudy className="weather-icon" />;
    }
    else if (lowerCondition.includes('rain') || lowerCondition.includes('drizzle')) {
      return <WiRain className="weather-icon" />;
    }
    else if (lowerCondition.includes('thunder')) {
      return <WiThunderstorm className="weather-icon" />;
    }
    else if (lowerCondition.includes('snow')) {
      return <WiSnow className="weather-icon" />;
    }
    else if (lowerCondition.includes('mist') || lowerCondition.includes('fog') || 
             lowerCondition.includes('haze') || lowerCondition.includes('smoke') ||
             lowerCondition.includes('dust')) {
      return <WiFog className="weather-icon" />;
    }
    else {
      return <WiDaySunny className="weather-icon" />; // Default icon
    }
  };

  export default WeatherIcon;
